package tv.vela.launcher;

import java.io.*;
import java.net.*;
import java.util.*;
import org.json.*;

/** Small catalog queries and server filter descriptors. No artwork or full media catalog is retained. */
final class CatalogFilters {
    static final int CHOICES=24,MAX_VALUES=24,MAX_TERMS=2048;
    static final class Query {
        String sort="",search="";boolean descending=true;
        final LinkedHashMap<String,List<Choice>> values=new LinkedHashMap<>();
        Query copy(){Query q=new Query();q.sort=sort;q.search=search;q.descending=descending;for(Map.Entry<String,List<Choice>> e:values.entrySet())q.values.put(e.getKey(),new ArrayList<>(e.getValue()));return q;}
        int count(){int n=search.isEmpty()?0:1;for(List<Choice> v:values.values())n+=v.size();return n;}
        boolean selected(String field,String value){for(Choice c:values.getOrDefault(field,Collections.emptyList()))if(c.value.equals(value))return true;return false;}
        void toggle(Facet field,Choice choice){List<Choice> list=new ArrayList<>(values.getOrDefault(field.id,Collections.emptyList()));if(selected(field.id,choice.value))list.removeIf(c->c.value.equals(choice.value));else{if(count()>=MAX_VALUES&&(field.multiple||list.isEmpty()))return;if(!field.multiple)list.clear();list.add(choice);}if(list.isEmpty())values.remove(field.id);else values.put(field.id,list);}
    }
    static final class Choice {final String value,title;Choice(String value,String title){this.value=value;this.title=title;}}
    static final class Facet {
        final String id,title,path;final boolean multiple;final List<Choice> fixed;
        Facet(String id,String title,String path,boolean multi,List<Choice> fixed){this.id=id;this.title=title;this.path=path;multiple=multi;this.fixed=fixed;}
    }
    static final class Sort {final String key,title;Sort(String key,String title){this.key=key;this.title=title;}}
    static final class Options {final List<Facet> facets=new ArrayList<>();final List<Sort> sorts=new ArrayList<>();}
    static final class Choices {final List<Choice> items;final int offset,total,received;Choices(List<Choice> i,int o,int t){this(i,o,t,i.size());}Choices(List<Choice> i,int o,int t,int n){items=i;offset=o;total=t;received=n;}boolean next(){return received>0&&offset+received<total;}int nextOffset(){return offset+received;}}
    static boolean field(String key){return key!=null&&key.matches("[a-zA-Z][a-zA-Z0-9_.]{0,63}")&&!Arrays.asList("sort","type","limit","offset","startindex","userid","parentid","includeitemtypes","uri","token").contains(key.toLowerCase(Locale.ROOT));}
    static String encode(String value)throws IOException{return URLEncoder.encode(value,"UTF-8");}
    static String text(String s){return s==null?"":s.substring(0,Math.min(240,s.length()));}
    static String join(List<Choice> choices,String delimiter)throws IOException{List<String> result=new ArrayList<>();if(choices.size()>MAX_VALUES)throw new IOException("Too many selections");for(Choice c:choices){if(c.value.length()>240||c.value.contains(delimiter)||c.value.indexOf('\n')>=0)throw new IOException("Invalid filter choice");result.add(c.value);}return String.join(delimiter,result);}
    static String plexPath(PlexClient.Section s,int offset,Query q)throws IOException{
        if(!s.key.matches("[0-9]+")||offset<0||q.count()>MAX_VALUES||q.search.length()>240)throw new IOException("Invalid catalog query");String sort=q.sort.isEmpty()?"addedAt":q.sort;if(!field(sort)||sort.toLowerCase(Locale.ROOT).contains("random"))throw new IOException("Invalid catalog order");
        StringBuilder path=new StringBuilder("/library/sections/"+s.key+"/all?type="+(s.type.equals("show")?2:1)+"&sort="+encode(sort+(q.descending?":desc":":asc")+(sort.equals("titleSort")?"":",titleSort:asc"))+"&includeExternalMetadata=0&X-Plex-Container-Start="+offset+"&X-Plex-Container-Size="+PlexClient.PAGE_SIZE);
        if(!q.search.isEmpty())path.append("&title=").append(encode(q.search));
        for(Map.Entry<String,List<Choice>> e:q.values.entrySet()){String key=e.getKey();if(key.equals("$state")){String value=join(e.getValue(),",");if(value.equals("unwatched"))path.append("&unwatched=1");else if(value.equals("watched"))path.append("&unwatched=0");else if(value.equals("progress"))path.append("&inProgress=1");else throw new IOException("Invalid state");}else{if(!field(key))throw new IOException("Invalid filter");path.append('&').append(encode(key)).append('=').append(encode(join(e.getValue(),",")));}}return path.toString();
    }
    static String jellyfinQuery(Query q)throws IOException{
        if(q.count()>MAX_VALUES||q.search.length()>240)throw new IOException("Invalid catalog query");String sort=q.sort.isEmpty()?"DateCreated":q.sort;if(!JF_SORTS.contains(sort))throw new IOException("Invalid catalog order");StringBuilder out=new StringBuilder("&sortBy="+sort+(sort.equals("SortName")?"":",SortName")+"&sortOrder="+(q.descending?"Descending":"Ascending")+(sort.equals("SortName")?"":",Ascending"));
        if(!q.search.isEmpty())out.append("&searchTerm=").append(encode(q.search));
        for(Map.Entry<String,List<Choice>> e:q.values.entrySet()){String key=e.getKey();if(key.equals("$state")){String value=join(e.getValue(),",");if(value.equals("unwatched"))out.append("&isPlayed=false");else if(value.equals("watched"))out.append("&isPlayed=true");else if(value.equals("progress"))out.append("&filters=IsResumable");else throw new IOException("Invalid state");}else{if(!JF_FIELDS.contains(key))throw new IOException("Invalid filter");String delimiter=Arrays.asList("genres","tags","officialRatings","studios").contains(key)?"|":",";out.append('&').append(key).append('=').append(encode(join(e.getValue(),delimiter)));}}return out.toString();
    }
    static final List<String> JF_SORTS=Arrays.asList("DateCreated","SortName","PremiereDate","ProductionYear","CommunityRating","CriticRating","DatePlayed","PlayCount","Runtime","DateLastContentAdded","SeriesDatePlayed","OfficialRating","VideoBitRate","Studio");
    private static final List<String> JF_FIELDS=Arrays.asList("genreIds","genres","years","officialRatings","tags","audioLanguages","subtitleLanguages","studioIds","personIds","isFavorite","hasSubtitles","is3D","isHd","is4K","minCommunityRating","seriesStatus","videoTypes");
    static Facet fixed(String id,String title,boolean multiple,String... values){List<Choice> choices=new ArrayList<>();for(String v:values)choices.add(new Choice(v,v));return new Facet(id,title,"",multiple,choices);}
    static Options defaults(boolean jellyfin,boolean series){Options out=new Options();out.facets.add(fixed("$state","Watch status",false,"unwatched","watched","progress"));for(String key:jellyfin?JF_SORTS:Arrays.asList("addedAt","titleSort","year","originallyAvailableAt","rating","audienceRating","userRating","duration","lastViewedAt","viewCount")){if(!series&&(key.equals("DateLastContentAdded")||key.equals("SeriesDatePlayed")))continue;out.sorts.add(new Sort(key,key));}return out;}
    static Options plexOptions(JSONObject root,PlexClient.Section section)throws IOException{
        Options out=defaults(false,section.type.equals("show"));JSONObject container=root.optJSONObject("MediaContainer"),meta=container==null?null:container.optJSONObject("Meta");JSONArray types=meta==null?null:meta.optJSONArray("Type");String target=section.type.equals("show")?"show":"movie";
        for(int i=0;types!=null&&i<Math.min(12,types.length());i++){JSONObject type=types.optJSONObject(i);if(type==null||!target.equals(type.optString("type")))continue;JSONArray sorts=type.optJSONArray("Sort");if(sorts!=null){out.sorts.clear();out.sorts.add(new Sort("addedAt","addedAt"));Set<String> seen=new HashSet<>();seen.add("addedAt");for(int n=0;n<Math.min(32,sorts.length());n++){JSONObject sort=sorts.optJSONObject(n);if(sort==null)continue;String key=sort.optString("key").split(":")[0];if(field(key)&&!key.toLowerCase(Locale.ROOT).contains("random")&&seen.add(key))out.sorts.add(new Sort(key,text(sort.optString("title",key))));}}
            JSONArray filters=type.optJSONArray("Filter");Set<String> seen=new HashSet<>();for(int n=0;filters!=null&&n<Math.min(48,filters.length());n++){JSONObject f=filters.optJSONObject(n);if(f==null)continue;String id=f.optString("filter"),route=safePlexFacet(f.optString("key"),section);if(!field(id)||route.isEmpty()||!seen.add(id))continue;out.facets.add(new Facet(id,text(f.optString("title",id)),route,true,Collections.emptyList()));}break;}return out;
    }
    static String safePlexFacet(String path,PlexClient.Section section){try{URI u=new URI(path);String prefix="/library/sections/"+section.key+"/";if(u.isAbsolute()||u.getRawAuthority()!=null||u.getRawFragment()!=null||u.getPath()==null)return "";String leaf=u.getPath().startsWith(prefix)?u.getPath().substring(prefix.length()):u.getPath().startsWith("/")?"":u.getPath();if(!leaf.matches("[a-zA-Z][a-zA-Z0-9]{0,48}"))return "";String query=u.getRawQuery();if(query!=null&&!query.matches("type=[0-9]{1,2}"))return "";return prefix+leaf+(query==null?"":"?"+query);}catch(Exception bad){return "";}}
    static Options jellyfinOptions(JSONObject legacy,JSONObject modern,PlexClient.Section section)throws IOException{
        Options out=defaults(true,section.type.equals("show"));out.facets.add(fixed("isFavorite","Favorites",false,"true","false"));JSONArray genres=modern.optJSONArray("Genres");List<Choice> ids=new ArrayList<>();for(int i=0;genres!=null&&i<Math.min(MAX_TERMS,genres.length());i++){JSONObject g=genres.optJSONObject(i);if(g!=null&&!JellyfinClient.id(g.optString("Id")).isEmpty())ids.add(new Choice(JellyfinClient.id(g.optString("Id")),text(g.optString("Name"))));}if(!ids.isEmpty())out.facets.add(new Facet("genreIds","Genre","",true,ids));else addTerms(out,"genres","Genre",legacy.optJSONArray("Genres"));
        addTerms(out,"years","Year",legacy.optJSONArray("Years"));addTerms(out,"officialRatings","Content rating",legacy.optJSONArray("OfficialRatings"));addTerms(out,"tags","Tags",modern.optJSONArray("Tags")!=null?modern.optJSONArray("Tags"):legacy.optJSONArray("Tags"));
        for(String[] field:new String[][]{{"audioLanguages","AudioLanguages","Audio language"},{"subtitleLanguages","SubtitleLanguages","Subtitle language"}}){JSONArray terms=modern.optJSONArray(field[1]);List<Choice> choices=new ArrayList<>();for(int i=0;terms!=null&&i<Math.min(MAX_TERMS,terms.length());i++){JSONObject term=terms.optJSONObject(i);if(term!=null&&!term.optString("Value").isEmpty())choices.add(new Choice(text(term.optString("Value")),text(term.optString("Name",term.optString("Value")))));}if(!choices.isEmpty())out.facets.add(new Facet(field[0],field[2],"",true,choices));}
        out.facets.add(new Facet("studioIds","Studio","/Studios",true,Collections.emptyList()));out.facets.add(new Facet("personIds","People","/Persons",true,Collections.emptyList()));out.facets.add(fixed("minCommunityRating","Minimum rating",false,"6","7","8","9"));for(String key:Arrays.asList("hasSubtitles","is3D","isHd","is4K"))out.facets.add(fixed(key,key,false,"true","false"));if(section.type.equals("show"))out.facets.add(fixed("seriesStatus","Series status",false,"Continuing","Ended","Unreleased"));return out;
    }
    private static void addTerms(Options o,String id,String title,JSONArray terms)throws IOException{if(terms==null)return;if(terms.length()>MAX_TERMS)throw new IOException("Filter metadata limit");List<Choice> values=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<terms.length();i++){String value=text(terms.optString(i));if(!value.isEmpty()&&seen.add(value))values.add(new Choice(value,value));}if(!values.isEmpty())o.facets.add(new Facet(id,title,"",true,values));}
    static Choices slice(List<Choice> all,int offset,String search)throws IOException{if(offset<0)throw new IOException("Invalid filter page");List<Choice> matching=new ArrayList<>();String term=search.toLowerCase(Locale.ROOT);for(Choice c:all)if(c.title.toLowerCase(Locale.ROOT).contains(term))matching.add(c);int start=Math.min(offset,matching.size());return new Choices(new ArrayList<>(matching.subList(start,Math.min(start+CHOICES,matching.size()))),offset,matching.size());}
    static Choices jellyfinChoices(JSONObject response,int offset)throws IOException{JSONArray items=response.optJSONArray("Items");int n=items==null?0:items.length();if(offset<0||n>CHOICES||response.optInt("StartIndex",offset)!=offset)throw new IOException("Filter paging mismatch");List<Choice> out=new ArrayList<>();for(int i=0;i<n;i++){JSONObject v=items.optJSONObject(i);if(v==null)continue;String id=JellyfinClient.id(v.optString("Id"));if(!id.isEmpty())out.add(new Choice(id,text(v.optString("Name"))));}return new Choices(out,offset,response.has("TotalRecordCount")?Math.max(0,response.optInt("TotalRecordCount")):offset+n+(n==CHOICES?1:0),n);}
    static Choices plexChoices(JSONObject root,int offset,String search)throws IOException{JSONObject c=root.optJSONObject("MediaContainer");JSONArray array=c==null?null:c.optJSONArray("Directory");if(array==null)return new Choices(Collections.emptyList(),offset,0);if(array.length()>MAX_TERMS)throw new IOException("Filter list limit");List<Choice> items=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<array.length();i++){JSONObject v=array.optJSONObject(i);if(v==null)continue;String value=text(v.optString("key")),title=text(v.optString("title"));if(!value.isEmpty()&&!title.isEmpty()&&seen.add(value))items.add(new Choice(value,title));}if(c.has("totalSize")&&c.optInt("totalSize")>array.length()){if(c.optInt("offset",offset)!=offset||array.length()>CHOICES)throw new IOException("Filter paging mismatch");return new Choices(items,offset,c.optInt("totalSize"),array.length());}return slice(items,offset,search);}
}
